INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('person-aquila-act18-introduction','person','ACT','{"id":"person-aquila-act18-introduction","title":"アキラ","summary":"ポントス出身のユダヤ人。妻プリスキラとともにイタリアから来ており、パウロが出会います。本文は、クラウディオのローマ退去命令を移動の背景として記しています。","passages":[{"book":"ACT","start":{"chapter":18,"verse":2},"end":{"chapter":18,"verse":2}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":2},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-18-2","title":"World English Bible · Acts 18:2","url":"https://ebible.org/engwebp/ACT18.htm#V2","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"person","details":{"identityNote":"このカードは、示した使徒言行録の場面だけを説明します。後の経歴は含めていません。"}}','primary-reviewed-2026-10-13.1','approved','1');
