INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('person-paul-act18-work','person','ACT','{"id":"person-paul-act18-work","title":"パウロ：共に働く","summary":"パウロはアキラたちと同業だったため、一緒に住んで働きます。仕事は天幕作りと記されています。材料や工程は、この場面では説明されません。","passages":[{"book":"ACT","start":{"chapter":18,"verse":2},"end":{"chapter":18,"verse":3}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":3},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-18-2","title":"World English Bible · Acts 18:2","url":"https://ebible.org/engwebp/ACT18.htm#V2","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"person","details":{"identityNote":"このカードは、示した使徒言行録の場面だけを説明します。後の経歴は含めていません。"}}','primary-reviewed-2026-10-13.1','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('person-crispus-act18','person','ACT','{"id":"person-crispus-act18","title":"クリスポ","summary":"会堂の指導者。家の者たちとともに主を信じた、と記されています。","passages":[{"book":"ACT","start":{"chapter":18,"verse":8},"end":{"chapter":18,"verse":8}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":8},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-18-8","title":"World English Bible · Acts 18:8","url":"https://ebible.org/engwebp/ACT18.htm#V8","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"person","details":{"identityNote":"このカードは、示した使徒言行録の場面だけを説明します。後の経歴は含めていません。"}}','primary-reviewed-2026-10-13.1','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('person-gallio-act18','person','ACT','{"id":"person-gallio-act18","title":"ガリオ","summary":"アカイアの地方総督。パウロへの訴えを聞きますが、言葉や名称、ユダヤ人自身の律法に関する争いの裁判官にはなりたくないと述べ、訴えた人々を裁判の席から追い払います。","passages":[{"book":"ACT","start":{"chapter":18,"verse":12},"end":{"chapter":18,"verse":16}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":16},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-18-12","title":"World English Bible · Acts 18:12","url":"https://ebible.org/engwebp/ACT18.htm#V12","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"person","details":{"identityNote":"本文が伝える役職と対応を説明しています。内心の動機や、ここにない年代は断定しません。"}}','primary-reviewed-2026-10-13.1','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('person-sosthenes-act18','person','ACT','{"id":"person-sosthenes-act18","title":"ソステネ","summary":"会堂の指導者として登場し、裁判の席の前で殴られます。","passages":[{"book":"ACT","start":{"chapter":18,"verse":17},"end":{"chapter":18,"verse":17}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":17},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-18-17","title":"World English Bible · Acts 18:17","url":"https://ebible.org/engwebp/ACT18.htm#V17","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"person","details":{"identityNote":"この箇所だけでは、他の箇所に登場する同名人物と同一人物かどうかは確定できません。"}}','primary-reviewed-2026-10-13.1','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('person-apollos-act18-introduction','person','ACT','{"id":"person-apollos-act18-introduction","title":"アポロ：エペソに来る","summary":"アレクサンドリア出身のユダヤ人。雄弁で、聖書に詳しい人物としてエペソに来ます。","passages":[{"book":"ACT","start":{"chapter":18,"verse":24},"end":{"chapter":18,"verse":24}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":24},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-18-24","title":"World English Bible · Acts 18:24","url":"https://ebible.org/engwebp/ACT18.htm#V24","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"person","details":{"identityNote":"このカードは、示した使徒言行録の場面だけを説明します。後の経歴は含めていません。"}}','primary-reviewed-2026-10-13.1','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('person-apollos-act18-learning','person','ACT','{"id":"person-apollos-act18-learning","title":"アポロ：教えを深める","summary":"熱心にイエスについて教えていましたが、知っていた洗礼はヨハネの洗礼でした。話を聞いたプリスキラとアキラが彼を招き、神の道をより正確に説明します。","passages":[{"book":"ACT","start":{"chapter":18,"verse":25},"end":{"chapter":18,"verse":26}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":26},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-18-25","title":"World English Bible · Acts 18:25","url":"https://ebible.org/engwebp/ACT18.htm#V25","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"person","details":{"identityNote":"本文は、プリスキラとアキラが補った説明の詳しい内容を記していません。"}}','primary-reviewed-2026-10-13.1','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('person-apollos-act18-achaia','person','ACT','{"id":"person-apollos-act18-achaia","title":"アポロ：アカイアへ","summary":"アカイアへ渡る際、仲間たちが現地の弟子たちに受け入れを求める手紙を書きます。到着後は信じた人々を助け、聖書からイエスがキリストであると示します。","passages":[{"book":"ACT","start":{"chapter":18,"verse":27},"end":{"chapter":18,"verse":28}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":28},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-18-27","title":"World English Bible · Acts 18:27","url":"https://ebible.org/engwebp/ACT18.htm#V27","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"person","details":{"identityNote":"このカードは、示した使徒言行録の場面だけを説明します。後の経歴は含めていません。"}}','primary-reviewed-2026-10-13.1','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('person-paul-act19-ephesus','person','ACT','{"id":"person-paul-act19-ephesus","title":"パウロ：エペソで弟子たちに会う","summary":"アポロがコリントにいたころ、パウロは内陸を通ってエペソに来て、何人かの弟子たちに会います。","passages":[{"book":"ACT","start":{"chapter":19,"verse":1},"end":{"chapter":19,"verse":1}}],"spoilerEnd":{"book":"ACT","chapter":19,"verse":1},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-19-1","title":"World English Bible · Acts 19:1","url":"https://ebible.org/engwebp/ACT19.htm#V1","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"person","details":{"identityNote":"このカードは、示した使徒言行録の場面だけを説明します。後の経歴は含めていません。"}}','primary-reviewed-2026-10-13.1','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('person-disciples-act19','person','ACT','{"id":"person-disciples-act19","title":"エペソの約十二人","summary":"パウロにヨハネの洗礼を受けたと答えた人々です。話を聞いて主イエスの名による洗礼を受け、パウロが手を置くと聖霊が臨み、異なる言葉を語り、預言したと記されています。人数は約十二人です。","passages":[{"book":"ACT","start":{"chapter":19,"verse":2},"end":{"chapter":19,"verse":7}}],"spoilerEnd":{"book":"ACT","chapter":19,"verse":7},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-19-2","title":"World English Bible · Acts 19:2","url":"https://ebible.org/engwebp/ACT19.htm#V2","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"person","details":{"identityNote":"個々の名前は書かれていません。十二使徒やアポロの弟子たちと同一視する根拠は、この箇所にはありません。"}}','primary-reviewed-2026-10-13.1','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('place-corinth','place','ACT','{"id":"place-corinth","title":"コリント","summary":"ギリシャ本土とペロポネソス半島をつなぐ陸路の要所にある古代都市です。使徒18章の冒頭では、パウロがアテネから到着します。","passages":[{"book":"ACT","start":{"chapter":18,"verse":1},"end":{"chapter":18,"verse":18}},{"book":"ACT","start":{"chapter":19,"verse":1},"end":{"chapter":19,"verse":1}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":1},"version":"primary-reviewed-2026-10-13.2","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-18-1","title":"World English Bible · Acts 18:1","url":"https://ebible.org/engwebp/ACT18.htm#V1","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"},{"id":"ascsa-corinth","title":"Corinth","url":"https://www.ascsa.edu.gr/publications/browse-by-series/corinth","publisher":"American School of Classical Studies at Athens","checkedAt":"2026-10-13","license":"citation-only"},{"id":"pleiades-570182","title":"Pleiades · Corinthus/Korinthos","url":"https://pleiades.stoa.org/places/570182","publisher":"Pleiades / Institute for the Study of the Ancient World, New York University","checkedAt":"2026-10-13","license":"cc-by-3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","attribution":"© G. Reger, J. McK. Camp II, Catherine Bouras, Brady Kiesling, R. Talbert, Chris de Lisle, Rosemary Selth, Jeffrey Becker, Sean Gillies, Tom Elliott, DARMC, James Herbst, R. Scott Smith, Greta Hawes. Pleiades, CC BY 3.0. 座標は原資料の代表点を転記。日本語説明は独自作成。"},{"id":"osm-way-224709706","title":"OpenStreetMap · ancient-site geometry","url":"https://www.openstreetmap.org/way/224709706","publisher":"OpenStreetMap contributors","checkedAt":"2026-10-13","license":"odbl-1.0","licenseUrl":"https://opendatacommons.org/licenses/odbl/1-0/","attribution":"© OpenStreetMap contributors. ODbL 1.0. Pleiades が用いた上流の位置資料。"}],"kind":"place","details":{"coordinates":{"latitude":37.90564164345828,"longitude":22.878614390874485,"certainty":"approximate","sourceId":"pleiades-570182","explanation":"古代コリント遺跡の代表点です。現代の市中心部や、本文の出来事の正確な場所を示すものではありません。背景の道路・海岸線は現代のものです。"},"identificationCertainty":"confirmed","modernName":"古代コリント遺跡（ギリシャ）"}}','primary-reviewed-2026-10-13.2','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('place-cenchreae','place','ACT','{"id":"place-cenchreae","title":"ケンクレア","summary":"コリントの東側の港として発掘研究が行われている場所です。使徒18:18では、誓願のために髪をそった場所として記されています。誓願の内容は、この節には書かれていません。","passages":[{"book":"ACT","start":{"chapter":18,"verse":18},"end":{"chapter":18,"verse":18}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":18},"version":"primary-reviewed-2026-10-13.2","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"web-act-18-18","title":"World English Bible · Acts 18:18","url":"https://ebible.org/engwebp/ACT18.htm#V18","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"},{"id":"ascsa-kenchreai-2007","title":"Life and Death at a Port in Roman Greece: The Kenchreai Cemetery Project, 2002–2006","url":"https://www.ascsa.edu.gr/publications/hesperia/article/76/1/143-181","publisher":"American School of Classical Studies at Athens","checkedAt":"2026-10-13","license":"citation-only"},{"id":"ascsa-kenchreai-2012","title":"Kenchreai, Eastern Port of Corinth: Discoveries from the Excavations on Koutsongila","url":"https://www.ascsa.edu.gr/index.php/news/newsDetails/report-on-kenchreai-2012","publisher":"American School of Classical Studies at Athens","checkedAt":"2026-10-13","license":"citation-only"},{"id":"pleiades-570347","title":"Pleiades · Kenchreai","url":"https://pleiades.stoa.org/places/570347","publisher":"Pleiades / Institute for the Study of the Ancient World, New York University","checkedAt":"2026-10-13","license":"cc-by-3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","attribution":"© G. Reger, J. McK. Camp II, DARMC, Brady Kiesling, Sean Gillies, Johan Åhlfeldt, Jeffrey Becker, Tom Elliott, Catherine Bouras, Gabriel Mckee, Joshua Sosin, R. Talbert. Pleiades, CC BY 3.0. 座標は原資料の代表点を転記。日本語説明は独自作成。"}],"kind":"place","details":{"coordinates":{"latitude":37.88239,"longitude":22.992532,"certainty":"approximate","sourceId":"pleiades-570347","explanation":"古代ケンクレアの港町を示す代表点です。本文の出来事の正確な場所を示すものではありません。背景の海岸線は現代のものです。"},"identificationCertainty":"confirmed","modernName":"Kenchreai（ギリシャ）"}}','primary-reviewed-2026-10-13.2','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('place-ephesus','place','ACT','{"id":"place-ephesus","title":"エペソ","summary":"現在のトルコ西部にある古代都市です。古代には海に面していましたが、川が運ぶ土砂によって港や水路の位置が移り変わりました。現在の遺跡の海岸からの距離を、そのまま当時の風景に当てはめることはできません。","passages":[{"book":"ACT","start":{"chapter":18,"verse":19},"end":{"chapter":18,"verse":21}},{"book":"ACT","start":{"chapter":18,"verse":24},"end":{"chapter":18,"verse":26}},{"book":"ACT","start":{"chapter":19,"verse":1},"end":{"chapter":19,"verse":7}}],"spoilerEnd":{"book":"ACT","chapter":18,"verse":19},"version":"primary-reviewed-2026-10-13.2","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"oeai-ephesos-2025","title":"130 years of the Austrian excavation at Ephesos","url":"https://www.oeaw.ac.at/en/oeai/media/news-archive/news-detail/130-jahre-oesterreichische-grabung-ephesos","publisher":"Austrian Archaeological Institute, Austrian Academy of Sciences","checkedAt":"2026-10-13","license":"citation-only"},{"id":"web-act-18-19","title":"World English Bible · Acts 18:19","url":"https://ebible.org/engwebp/ACT18.htm#V19","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"},{"id":"pleiades-599612","title":"Pleiades · Ephesus/Arsinoe(ia)","url":"https://pleiades.stoa.org/places/599612","publisher":"Pleiades / Institute for the Study of the Ancient World, New York University","checkedAt":"2026-10-13","license":"cc-by-3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","attribution":"© C. Foss, G. Reger, Brady Kiesling, Sean Gillies, Jeffrey Becker, H. Kopp, Joel Michael Kent, B. Siewert-Mayer, Phoebe Acheson, R. Talbert, Johan Åhlfeldt, W. Röllig, Adam Rabinowitz, Tom Elliott, DARMC, jfu, Chris de Lisle, Francis Deblauwe, R. Scott Smith, Greta Hawes, Ryan Horne, Eric Kansa. Pleiades, CC BY 3.0. 座標は原資料の代表点を転記。日本語説明は独自作成。"},{"id":"osm-way-244582409","title":"OpenStreetMap · ancient-site geometry","url":"https://www.openstreetmap.org/way/244582409","publisher":"OpenStreetMap contributors","checkedAt":"2026-10-13","license":"odbl-1.0","licenseUrl":"https://opendatacommons.org/licenses/odbl/1-0/","attribution":"© OpenStreetMap contributors. ODbL 1.0. Pleiades が用いた上流の位置資料。"}],"kind":"place","details":{"coordinates":{"latitude":37.940164271971945,"longitude":27.34240298195866,"certainty":"approximate","sourceId":"pleiades-599612","explanation":"エフェソス遺跡の代表点です。現代のセルチュク市中心部や、本文の出来事の正確な場所を示すものではありません。古代の港・海岸線は現在と異なります。"},"identificationCertainty":"confirmed","modernName":"Ephesos／エフェソス遺跡（トルコ）"}}','primary-reviewed-2026-10-13.2','approved','1');
INSERT OR REPLACE INTO public_materials(id,kind,book,data_json,version,rights_status,active) VALUES('art-tintoretto-conversion-paul','artwork','ACT','{"id":"art-tintoretto-conversion-paul","title":"ティントレット《聖パウロの回心》","summary":"ダマスコへ向かう途中で光を受け、地に倒れる場面を描いた16世紀の宗教画です。所蔵館は使徒9:3–7との関係を示しています。馬や多数の人物による劇的な構図は絵画表現として読み、本文の出来事と区別して見ます。","passages":[{"book":"ACT","start":{"chapter":9,"verse":3},"end":{"chapter":9,"verse":7}}],"spoilerEnd":{"book":"ACT","chapter":9,"verse":7},"version":"primary-reviewed-2026-10-13.1","reviewed":true,"rightsStatus":"approved","relationship":"direct","provenance":[{"id":"nga-46142","title":"The Conversion of Saint Paul","url":"https://www.nga.gov/artworks/46142-conversion-saint-paul","publisher":"National Gallery of Art","checkedAt":"2026-10-13","license":"citation-only"},{"id":"nga-open-access","title":"Open Access Policy for Images of Works of Art Presumed in the Public Domain","url":"https://www.nga.gov/terms-and-notices","publisher":"National Gallery of Art","checkedAt":"2026-10-13","license":"citation-only"},{"id":"web-act-9-3","title":"World English Bible · Acts 9:3","url":"https://ebible.org/engwebp/ACT09.htm#V3","publisher":"eBible.org","checkedAt":"2026-10-13","license":"public-domain"}],"kind":"artwork","details":{"artist":"Jacopo Tintoretto（ヤコポ・ティントレット）","yearLabel":"1544年頃","collection":"National Gallery of Art, Washington · Samuel H. Kress Collection · 1961.9.43","objectUrl":"https://www.nga.gov/artworks/46142-conversion-saint-paul","rightsStatement":"作品ページは、この作品の画像をパブリックドメインと明示しています。所蔵館の対象画像はCC0で提供されています。解説文全体の転載許可とは別です。","media":{"url":"https://api.nga.gov/iiif/50a2866d-de51-4824-a6b6-6c8643d94335/full/%21800%2C800/0/default.jpg","rights":"public-domain","rightsUrl":"https://www.nga.gov/terms-and-notices","attribution":"Jacopo Tintoretto, The Conversion of Saint Paul, c. 1544. Samuel H. Kress Collection, 1961.9.43. Courtesy National Gallery of Art, Washington.","checkedAt":"2026-10-13"}}}','primary-reviewed-2026-10-13.1','approved','1');
